-- GenDB engine variant Q13-commuted_comparisons: template q13.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  c_count,
  COUNT(*) AS custdist
FROM (
  SELECT
    c_custkey,
    COUNT(o_orderkey) AS c_count
  FROM customer
  LEFT OUTER JOIN orders
    ON o_custkey = c_custkey AND NOT o_comment LIKE $1
  GROUP BY
    c_custkey
) AS c_orders
GROUP BY
  c_count
ORDER BY
  custdist DESC,
  c_count DESC
